head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > setData]<br/>지정한 키로 데이터를 WebSquare 에 전역 변수로 등록합니다.",
    "validation" : [
        "key(필수) 파라미터로 데이터를 식별하기 위한 Key 값을 설정할 수 있어야 합니다.",
        "data(필수) 파라미터로 등록할 데이터를 설정할 수 있어야 합니다. 임의의 타입을 사용할 수 있어야 합니다.",
        "SPA 페이지 이동 시 등록된 키와 데이터가 자동으로 정리됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // SPA 재로딩 후 데이터 정리 여부 확인
    let spaCheck = sessionStorage.getItem("setData_spa_check");
    if (spaCheck) {
        let keys = JSON.parse(spaCheck);
        for (let i = 0; i < keys.length; i++) {
            let result = WebSquare.util.getData(keys[i]);
            wf_body_bottom.getObj("scwin").setReturnValue("SPA 재로딩 후 getData('" + keys[i] + "') : " + JSON.stringify(result));
        }
        sessionStorage.removeItem("setData_spa_check");
    }
};



scwin.btn_setData_onclick = function () {
    let dataType = par_dataType.getValue();
    let key = "testKey";
    let data;

    if (dataType === "Object") {
        data = {name: "테스트", value: 100};
    } else if (dataType === "Array") {
        data = [1, 2, 3];
    } else if (dataType === "String") {
        data = "문자열데이터";
    } else if (dataType === "Number") {
        data = 12345;
    } else if (dataType === "Function") {
        data = function() { return "함수실행결과"; };
    }

    // setData 실행
    WebSquare.util.setData(key, data);

    // getData 로 등록 확인
    let result = WebSquare.util.getData(key);
    if (typeof result === "function") {
        wf_body_bottom.getObj("scwin").setReturnValue("getData('" + key + "') : function (등록 확인)");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("getData('" + key + "') : " + JSON.stringify(result));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);

}



scwin.btn_reinitialize_onclick = function () {
    sessionStorage.setItem("setData_spa_check", JSON.stringify(["testKey"]));
    WebSquare.util.reinitialize(false);
}
